34	     * print out the metrics in alphabetical order
35	     * @param metrics   the metrics to be printed out
36	     */
37	    public static void printMetrics(Map<MetricName, ? extends Metric> metrics) {
38	        if (metrics != null && !metrics.isEmpty()) {
39	            int maxLengthOfDisplayName = 0;
40	            TreeMap<String, Object> sortedMetrics = new TreeMap<>();
41	            for (Metric metric : metrics.values()) {
42	                MetricName mName = metric.metricName();
43	                String mergedName = mName.group() + ":" + mName.name() + ":" + mName.tags();
44	                maxLengthOfDisplayName = Math.max(maxLengthOfDisplayName, mergedName.length());
45	                sortedMetrics.put(mergedName, metric.metricValue());
46	            }
47	            String doubleOutputFormat = "%-" + maxLengthOfDisplayName + "s : %.3f";
48	            String defaultOutputFormat = "%-" + maxLengthOfDisplayName + "s : %s";
49	            System.out.println(String.format("\n%-" + maxLengthOfDisplayName + "s   %s", "Metric Name", "Value"));
50	
51	            for (Map.Entry<String, Object> entry : sortedMetrics.entrySet()) {
52	                String outputFormat;
53	                if (entry.getValue() instanceof Double)
54	                    outputFormat = doubleOutputFormat;
55	                else
56	                    outputFormat = defaultOutputFormat;
57	                System.out.println(String.format(outputFormat, entry.getKey(), entry.getValue()));
58	            }
59	        }
60	    }
